"""Present pixels generated by ovrtx using the standalone ovui distribution."""
import numpy as np
import omni.ui as ui


class NativeView:
    def __init__(self, lab, product='Main', **kwargs):
        self.lab, self.product = lab, product
        self.updates_enabled = True
        self.pixels = None
        self.presented_size = None
        self.camera_pose = None
        self.gpu_frames = 0
        self.cursor = None
        self.hovered = False
        if product == 'Main':
            from .viewport_cursor import create_cursor
            self.cursor = create_cursor()
            hovered_fn = kwargs.pop('mouse_hovered_fn', None)
            def hovered(value):
                self.hovered = value
                if hovered_fn:
                    hovered_fn(value)
                self.update_cursor()
            kwargs['mouse_hovered_fn'] = hovered
        from omni.ui import _ui
        self.gpu_enabled = product == 'Main' and getattr(_ui, 'has_gpu_byte_image', lambda: False)()
        self.provider = ui.ByteImageProvider()
        # ovui's default widget hover includes areas covered by other windows.
        # Scene mouse callbacks must not see clicks on floating chat/settings
        # controls, otherwise mouse-down closes the chat before button release.
        kwargs.setdefault('explicit_hover', True)
        self.widget = ui.ImageWithProvider(self.provider,
            fill_policy=ui.IwpFillPolicy.IWP_PRESERVE_ASPECT_FIT, **kwargs)

    def update(self,pixels):
        if self.updates_enabled:
            self.pixels = pixels
            h,w=self.pixels.shape[:2]
            self.presented_size = (w, h)
            self.provider.set_data_array(np.ascontiguousarray(self.pixels).reshape(-1), [w,h])

    def present_gpu(self, mapped):
        """Copy a mapped RTX CUDA image into the UI while its lease is valid."""
        import warp
        frame = warp.from_dlpack(mapped)
        try:
            h, w = frame.shape[:2]
            self.provider.set_bytes_data_from_gpu(frame.ptr, [w, h], stride=frame.strides[0])
            self.presented_size = (w, h)
            self.pixels = None  # Never expose an old CPU frame as the current view.
            self.gpu_frames += 1
        finally:
            del frame

    def destroy(self):
        self.updates_enabled=False
        self.close_cursor()
        self.widget.destroy()

    def update_cursor(self):
        if self.cursor:
            self.cursor.update(self.hovered and self.updates_enabled, self.lab.dragging)

    def close_cursor(self):
        if self.cursor:
            self.cursor.close()
            self.cursor = None


class StreamView:
    def __init__(self,lab):
        self.lab=lab
        self.transport=None
        self.provider=ui.ByteImageProvider()
        self.widget=ui.ImageWithProvider(self.provider,height=180,fill_policy=ui.IwpFillPolicy.IWP_PRESERVE_ASPECT_FIT)
        self.error=lab.stream_error
        self.command_count=0
        self.last_command='none'
        self.last_pixels=None
        self.last_frame=0.

    def connect(self):
        from .stream_transport import LocalStream
        if self.transport:
            return
        try:
            if self.lab.stream_transport is None:
                self.lab.stream_transport=LocalStream()
            self.transport=self.lab.stream_transport
            self.lab.stream_error=None
            self.error=None
        except Exception as exc:
            self.error=str(exc)
            raise RuntimeError('Camera connection failed: '+str(exc)) from exc

    def send(self,text):
        if self.transport:
            self.transport.command(text)

    def update(self,frame):
        import time
        if not self.transport:
            return
        w=self.lab.gallery.workshops
        while self.transport.messages:
            command=self.transport.messages.popleft()
            w.stream_command(command)
            self.command_count+=1
            self.last_command=command
        now=time.monotonic()
        if not w.stream_paused and now-self.last_frame >= 1/w.stream_fps:
            self.last_frame=now
            pixels=self.transport.send(frame)
            if pixels is not None:
                self.last_pixels=pixels
                self.provider.set_data_array(pixels.reshape(-1),[640,360])

    def close(self):
        if self.transport:
            # The application owns the connection. Keep it warm between rooms;
            # a hidden panel must not retain queued client commands.
            self.transport.messages.clear()
            self.transport=None
        self.widget.destroy()
